/**
 * @fileoverview Official taxonomy artifact generator for the monorepo.
 * @module scripts/generate.artifacts
 *
 * @remarks
 * Downloads version-pinned official classification releases, normalizes them into a
 * shared artifact schema, and writes byte-identical minified JSON into both the API
 * and website runtime directories. Generated output is git-ignored and regenerated by
 * local setup, CI, and container builds before compilation.
 */

import {execFile} from "node:child_process";
import {glob, mkdir, mkdtemp, readFile, rm, writeFile} from "node:fs/promises";
import {EOL, tmpdir} from "node:os";
import {basename, dirname, join, resolve} from "node:path";
import {fileURLToPath} from "node:url";
import {promisify} from "node:util";
import type {NodePackageDependencyType, NodePackageInformation} from "./types";

const executeFile = promisify(execFile);

const GPC_LEVELS: Readonly<Record<number, string>> = {
  1: "segment",
  2: "family",
  3: "class",
  4: "brick",
};

const OUTPUT_ROOTS = [
  resolve("sites/api.arolariu.ro/src/Invoices/Resources/Taxonomies"),
  resolve("sites/arolariu.ro/src/data/taxonomies"),
] as const;

/** @internal */
export const FILE_NAMES = {
  GS1_GPC: "gpc-2026-05.min.json",
  ECOICOP_V2: "ecoicop-v2.min.json",
  NACE_2_1: "nace-2.1.min.json",
} as const satisfies Readonly<Record<ArtifactClassificationSystem, string>>;

/** Classification systems supported by generated artifacts. */
export type ArtifactClassificationSystem = "GS1_GPC" | "ECOICOP_V2" | "NACE_2_1";

/** Single normalized taxonomy node. */
export interface TaxonomyArtifactNode {
  readonly code: string;
  readonly officialLabel: string;
  readonly level: string;
  readonly parentCode: string | null;
  readonly hierarchyCodes: readonly string[];
  readonly hierarchyLabels: readonly string[];
  readonly definition: string | null;
  readonly searchText: string;
}

/** Versioned taxonomy artifact consumed by the API and the website. */
export interface TaxonomyArtifact {
  readonly system: ArtifactClassificationSystem;
  readonly version: string;
  readonly sourceUrl: string;
  readonly generatedAt: string;
  readonly attribution: string;
  readonly nodes: readonly TaxonomyArtifactNode[];
}

/** Shape used by the official GS1 GPC JSON document. */
export interface GpcSourceNode {
  readonly Level: number;
  readonly Code: number;
  readonly Title: string;
  readonly Definition: string | null;
  readonly DefinitionExcludes: string | null;
  readonly Active: boolean;
  readonly Childs: readonly GpcSourceNode[];
}

/** Root shape of the official GS1 GPC JSON document. */
export interface GpcSourceDocument {
  readonly LanguageCode: string;
  readonly DateUtc: string;
  readonly Schema: readonly GpcSourceNode[];
}

/** Simplified SPARQL row used by taxonomy normalization. */
export interface SparqlBindingInput {
  readonly concept: string;
  readonly notation: string;
  readonly label: string;
  readonly broader: string | null;
}

/** Generates one classification taxonomy and writes its runtime artifacts. */
export abstract class TaxonomyClassificationGenerator {
  /** Generates the classification artifact and returns every output path. */
  public abstract generate(): Promise<readonly string[]>;
}

/** Generates one family of third-party license documents. */
export abstract class LicenseGenerator {
  /** Generates the license document and returns every output path. */
  public abstract generate(): Promise<readonly string[]>;
}

/** Reserved backend license generator; backend discovery is intentionally deferred. */
export class BackendLicenseGenerator extends LicenseGenerator {
  /** Returns no outputs until backend license discovery is defined. */
  public override async generate(): Promise<readonly string[]> {
    return [];
  }
}

function readJsonRecord(contents: string, manifestPath: string): Readonly<Record<string, unknown>> {
  const parsed: unknown = JSON.parse(contents);
  if (!isRecord(parsed)) throw new TypeError(`Package manifest '${manifestPath}' must be an object.`);
  return parsed;
}

function readOptionalManifestString(
  manifest: Readonly<Record<string, unknown>>,
  key: string,
  manifestPath: string,
): string | undefined {
  const value = manifest[key];
  if (value === undefined) return undefined;
  if (typeof value !== "string") {
    throw new TypeError(`Package manifest '${manifestPath}' field '${key}' must be a string.`);
  }
  return value;
}

function readDependencyMap(
  manifest: Readonly<Record<string, unknown>>,
  key: string,
  manifestPath: string,
): Readonly<Record<string, string>> {
  const value = manifest[key];
  if (value === undefined) return {};
  if (!isRecord(value)) {
    throw new TypeError(`Package manifest '${manifestPath}' field '${key}' must be an object.`);
  }

  const dependencies: Record<string, string> = {};
  for (const [name, version] of Object.entries(value)) {
    if (typeof version !== "string") {
      throw new TypeError(`Package manifest '${manifestPath}' dependency '${name}' must have a string version.`);
    }
    dependencies[name] = version;
  }
  return dependencies;
}

async function readDeclaredFrontendDependencies(
  workspaceRoot: string,
): Promise<ReadonlyMap<NodePackageDependencyType, readonly string[]>> {
  const manifestPath = join(workspaceRoot, "sites", "arolariu.ro", "package.json");
  const manifest = readJsonRecord(await readFile(manifestPath, "utf8"), manifestPath);

  return new Map<NodePackageDependencyType, readonly string[]>([
    ["production", Object.keys(readDependencyMap(manifest, "dependencies", manifestPath))],
    ["development", Object.keys(readDependencyMap(manifest, "devDependencies", manifestPath))],
    ["peer", Object.keys(readDependencyMap(manifest, "peerDependencies", manifestPath))],
  ]);
}

async function findDirectInstalledPackageManifestPaths(workspaceRoot: string): Promise<readonly string[]> {
  const nodeModulesRoot = join(workspaceRoot, "node_modules");
  const paths: string[] = [];
  for await (const manifestPath of glob(["*/package.json", "@*/*/package.json"], {cwd: nodeModulesRoot})) {
    paths.push(join(nodeModulesRoot, manifestPath));
  }
  return paths;
}

function resolveDependencyType(
  packageName: string,
  declaredDependencies: ReadonlyMap<NodePackageDependencyType, readonly string[]>,
): NodePackageDependencyType | null {
  for (const dependencyType of ["production", "development", "peer"] as const) {
    if (declaredDependencies.get(dependencyType)?.includes(packageName) === true) return dependencyType;
  }
  return null;
}

async function readInstalledPackageInformation(
  manifestPath: string,
  declaredDependencies: ReadonlyMap<NodePackageDependencyType, readonly string[]>,
): Promise<Readonly<{dependencyType: NodePackageDependencyType; packageInformation: NodePackageInformation}> | null> {
  const manifest = readJsonRecord(await readFile(manifestPath, "utf8"), manifestPath);
  const packageName = readOptionalManifestString(manifest, "name", manifestPath) ?? basename(dirname(manifestPath));
  const dependencyType = resolveDependencyType(packageName, declaredDependencies);
  if (dependencyType === null) return null;

  const authorValue = manifest["author"];
  let author = "unknown";
  if (typeof authorValue === "string") {
    author = authorValue;
  } else if (isRecord(authorValue) && typeof authorValue["name"] === "string") {
    author = authorValue["name"];
  } else if (authorValue !== undefined) {
    throw new TypeError(`Package manifest '${manifestPath}' field 'author' must be a string or named object.`);
  }

  const repositoryValue = manifest["repository"];
  let repositoryUrl: string | undefined;
  if (typeof repositoryValue === "string") {
    repositoryUrl = repositoryValue;
  } else if (isRecord(repositoryValue) && typeof repositoryValue["url"] === "string") {
    repositoryUrl = repositoryValue["url"];
  } else if (repositoryValue !== undefined) {
    throw new TypeError(`Package manifest '${manifestPath}' field 'repository' must be a string or URL object.`);
  }

  const dependencyMaps = [
    readDependencyMap(manifest, "dependencies", manifestPath),
    readDependencyMap(manifest, "devDependencies", manifestPath),
    readDependencyMap(manifest, "peerDependencies", manifestPath),
  ];
  const dependents = dependencyMaps.flatMap((dependencies) =>
    Object.entries(dependencies).map(([name, version]) => ({name, version})),
  );

  return {
    dependencyType,
    packageInformation: {
      name: packageName,
      author,
      description:
        readOptionalManifestString(manifest, "description", manifestPath)
        ?? "This package has not provided a valid description.",
      homepage: readOptionalManifestString(manifest, "homepage", manifestPath) ?? repositoryUrl ?? "unknown",
      license: readOptionalManifestString(manifest, "license", manifestPath) ?? "unknown",
      version: readOptionalManifestString(manifest, "version", manifestPath) ?? "unknown",
      dependents,
    },
  };
}

async function writeFrontendLicenseDocument(
  workspaceRoot: string,
  packages: ReadonlyMap<NodePackageDependencyType, readonly NodePackageInformation[]>,
): Promise<string> {
  const outputPath = join(workspaceRoot, "sites", "arolariu.ro", "licenses.json");
  const sortedPackages = new Map<NodePackageDependencyType, readonly NodePackageInformation[]>();
  for (const [dependencyType, packageInformation] of packages) {
    sortedPackages.set(
      dependencyType,
      packageInformation.toSorted((left, right) => left.name.localeCompare(right.name)),
    );
  }

  await mkdir(dirname(outputPath), {recursive: true});
  await writeFile(outputPath, `${JSON.stringify(Object.fromEntries(sortedPackages))}${EOL}`, "utf8");
  return outputPath;
}

/** Generates the frontend third-party license document. */
export class FrontendLicenseGenerator extends LicenseGenerator {
  /** Creates the generator. */
  public constructor(private readonly workspaceRoot: string = process.cwd()) {
    super();
  }

  /** Reads direct frontend dependencies and writes licenses.json. */
  public override async generate(): Promise<readonly string[]> {
    const declaredDependencies = await readDeclaredFrontendDependencies(this.workspaceRoot);
    const manifestPaths = await findDirectInstalledPackageManifestPaths(this.workspaceRoot);
    const resolvedPackages = await Promise.all(
      manifestPaths.map((manifestPath) => readInstalledPackageInformation(manifestPath, declaredDependencies)),
    );
    const groupedPackages = new Map<NodePackageDependencyType, NodePackageInformation[]>();

    for (const resolvedPackage of resolvedPackages) {
      if (resolvedPackage === null) continue;
      const packages = groupedPackages.get(resolvedPackage.dependencyType) ?? [];
      packages.push(resolvedPackage.packageInformation);
      groupedPackages.set(resolvedPackage.dependencyType, packages);
    }

    return [await writeFrontendLicenseDocument(this.workspaceRoot, groupedPackages)];
  }
}

/** Shell-independent command used to extract a ZIP archive. */
export interface ArchiveExtractionCommand {
  readonly command: string;
  readonly args: readonly string[];
}

/**
 * Builds the platform-specific ZIP extraction command.
 *
 * @param platform - Node platform identifier.
 * @param archivePath - ZIP archive path.
 * @param outputDirectory - Destination directory.
 * @returns Executable and argument list.
 */
export function buildArchiveExtractionCommand(
  platform: NodeJS.Platform,
  archivePath: string,
  outputDirectory: string,
): ArchiveExtractionCommand {
  return platform === "win32"
    ? {command: "tar.exe", args: ["-xf", archivePath, "-C", outputDirectory]}
    : {command: "unzip", args: ["-qq", archivePath, "-d", outputDirectory]};
}

function hasErrorCode(error: unknown): error is Error & Readonly<{code: string}> {
  return error instanceof Error && "code" in error && typeof Reflect.get(error, "code") === "string";
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function requireString(record: Readonly<Record<string, unknown>>, key: string, context: string): string {
  const value = record[key];
  if (typeof value !== "string") throw new Error(`${context} ${key} must be a string.`);
  if (value.trim().length === 0) throw new Error(`${context} ${key} must be a non-empty string.`);
  return value;
}

function optionalString(record: Readonly<Record<string, unknown>>, key: string, context: string): string | null {
  const value = record[key];
  if (value === null || value === undefined) return null;
  if (typeof value !== "string") throw new Error(`${context} ${key} must be a string or null.`);
  return value;
}

function requireNumber(record: Readonly<Record<string, unknown>>, key: string, context: string): number {
  const value = record[key];
  if (typeof value !== "number" || !Number.isFinite(value)) throw new Error(`${context} ${key} must be a number.`);
  return value;
}

function requireBoolean(record: Readonly<Record<string, unknown>>, key: string, context: string): boolean {
  const value = record[key];
  if (typeof value !== "boolean") throw new Error(`${context} ${key} must be a boolean.`);
  return value;
}

function parseGpcNode(value: unknown): GpcSourceNode {
  if (!isRecord(value)) throw new Error("GPC node must be an object.");
  const children = value["Childs"];
  if (!Array.isArray(children)) throw new Error("GPC node Childs must be an array.");

  return {
    Level: requireNumber(value, "Level", "GPC node"),
    Code: requireNumber(value, "Code", "GPC node"),
    Title: requireString(value, "Title", "GPC node"),
    Definition: optionalString(value, "Definition", "GPC node"),
    DefinitionExcludes: optionalString(value, "DefinitionExcludes", "GPC node"),
    Active: requireBoolean(value, "Active", "GPC node"),
    Childs: children.map((child: unknown) => parseGpcNode(child)),
  };
}

function normalizeText(...parts: readonly (string | null | undefined)[]): string {
  return parts
    .filter((part): part is string => typeof part === "string" && part.trim().length > 0)
    .join(" ")
    .normalize("NFKD")
    .replace(/\p{Mark}+/gu, "")
    .toLocaleLowerCase("en")
    .replace(/[^\p{Letter}\p{Number}.]+/gu, " ")
    .trim()
    .replace(/\s+/gu, " ");
}

function stripCodePrefix(label: string, notation: string): string {
  const trimmed = label.trim();
  if (!trimmed.startsWith(notation)) return trimmed;
  const withoutNotation = trimmed
    .slice(notation.length)
    .replace(/^[\s:–—-]+/u, "")
    .trim();
  return withoutNotation.length > 0 ? withoutNotation : trimmed;
}

function getEuLevel(system: Exclude<ArtifactClassificationSystem, "GS1_GPC">, code: string): string {
  if (system === "ECOICOP_V2") {
    const segmentCount = code.split(".").length;
    return ["division", "group", "class", "subclass"][segmentCount - 1] ?? `level-${segmentCount}`;
  }

  if (/^[A-Z]$/u.test(code)) return "section";
  if (/^\d{2}$/u.test(code)) return "division";
  if (/^\d{2}\.\d$/u.test(code)) return "group";
  if (/^\d{2}\.\d{2}$/u.test(code)) return "class";
  return "code";
}

/**
 * Parses and validates the official GS1 GPC JSON document.
 *
 * @param value - Untrusted parsed JSON.
 * @returns Strongly typed source document.
 * @throws {Error} When any required field is missing or has the wrong type.
 */
export function parseGpcDocument(value: unknown): GpcSourceDocument {
  if (!isRecord(value)) throw new Error("GPC document must be an object.");
  const schema = value["Schema"];
  if (!Array.isArray(schema)) throw new Error("GPC document Schema must be an array.");

  return {
    LanguageCode: requireString(value, "LanguageCode", "GPC document"),
    DateUtc: requireString(value, "DateUtc", "GPC document"),
    Schema: schema.map((node: unknown) => parseGpcNode(node)),
  };
}

/**
 * Flattens the official hierarchical GPC schema into Segment through Brick nodes.
 *
 * @remarks
 * Inactive nodes and their descendants are excluded. Nodes whose level falls outside
 * 1-4 are omitted from the output but their children are still visited, so deeper
 * classification levels are preserved.
 *
 * @param schema - Official GPC schema nodes.
 * @returns Normalized active nodes for levels 1-4, in document order.
 */
export function flattenGpcSchema(schema: readonly GpcSourceNode[]): readonly TaxonomyArtifactNode[] {
  const nodes: TaxonomyArtifactNode[] = [];

  const visit = (node: GpcSourceNode, ancestors: readonly TaxonomyArtifactNode[]): void => {
    if (!node.Active) return;

    const level = GPC_LEVELS[node.Level];
    const title = node.Title.trim();
    const definition = node.Definition?.trim() ? node.Definition.trim() : null;

    const current: TaxonomyArtifactNode | null =
      level === undefined
        ? null
        : {
            code: String(node.Code),
            officialLabel: title,
            level,
            parentCode: ancestors.at(-1)?.code ?? null,
            hierarchyCodes: [...ancestors.map((ancestor) => ancestor.code), String(node.Code)],
            hierarchyLabels: [...ancestors.map((ancestor) => ancestor.officialLabel), title],
            definition,
            searchText: normalizeText(
              String(node.Code),
              title,
              definition,
              ...ancestors.map((ancestor) => ancestor.officialLabel),
            ),
          };

    if (current !== null) nodes.push(current);
    const nextAncestors = current === null ? ancestors : [...ancestors, current];
    for (const child of node.Childs) visit(child, nextAncestors);
  };

  for (const root of schema) visit(root, []);
  return nodes;
}

/**
 * Resolves a node and rebuilds its full hierarchy by walking parent links.
 *
 * @param nodes - Normalized nodes containing the target and all of its ancestors.
 * @param code - Node code to resolve.
 * @returns The node with a rebuilt hierarchy and recomputed search text.
 * @throws {Error} When the code is absent, a parent reference dangles, or the parent
 * chain contains a cycle.
 */
export function buildHierarchy(nodes: readonly TaxonomyArtifactNode[], code: string): TaxonomyArtifactNode {
  const nodesByCode = new Map(nodes.map((node) => [node.code, node] as const));
  const selected = nodesByCode.get(code);
  if (selected === undefined) throw new Error(`Taxonomy code '${code}' was not found.`);

  const hierarchy: TaxonomyArtifactNode[] = [];
  const visited = new Set<string>();
  let current: TaxonomyArtifactNode | undefined = selected;

  while (current !== undefined) {
    if (visited.has(current.code)) throw new Error(`Taxonomy hierarchy cycle detected at '${current.code}'.`);
    visited.add(current.code);
    hierarchy.unshift(current);

    if (current.parentCode === null) break;
    const parent = nodesByCode.get(current.parentCode);
    if (parent === undefined) {
      throw new Error(`Taxonomy parent '${current.parentCode}' for '${current.code}' was not found.`);
    }
    current = parent;
  }

  return {
    ...selected,
    hierarchyCodes: hierarchy.map((node) => node.code),
    hierarchyLabels: hierarchy.map((node) => node.officialLabel),
    searchText: normalizeText(
      selected.code,
      selected.officialLabel,
      selected.definition,
      ...hierarchy.map((node) => node.officialLabel),
    ),
  };
}

const SPARQL_ENDPOINT = "https://publications.europa.eu/webapi/rdf/sparql";
const ECOICOP_SCHEME = "http://data.europa.eu/ed1/ecoicop2/ecoicop2";
const NACE_SCHEME = "http://data.europa.eu/ux2/nace2.1/nace2.1";
const SPARQL_PAGE_SIZE = 5_000;
const EU_ATTRIBUTION =
  "European Union, Publications Office of the European Union, reused under the European Commission reuse policy.";

function createSparqlQuery(scheme: string, offset: number): string {
  return `
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?concept ?notation ?label ?broader WHERE {
  ?concept skos:inScheme <${scheme}> ;
           skos:notation ?notation ;
           skos:prefLabel ?label .
  OPTIONAL { ?concept skos:broader ?broader . }
  FILTER(lang(?label) = "en")
}
ORDER BY ?notation
LIMIT ${SPARQL_PAGE_SIZE}
OFFSET ${offset}`;
}

function readBindingValue(binding: Readonly<Record<string, unknown>>, key: string, required: boolean): string | null {
  const valueRecord = binding[key];
  if (valueRecord === undefined) {
    if (!required) return null;
    throw new TypeError(`SPARQL binding '${key}' is required.`);
  }

  if (!isRecord(valueRecord)) throw new TypeError(`SPARQL binding '${key}' must be an object.`);
  const value = valueRecord["value"];
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`SPARQL binding '${key}'.value must be a non-empty string.`);
  }
  return value;
}

function parseSparqlResponse(value: unknown): readonly SparqlBindingInput[] {
  if (!isRecord(value)) throw new TypeError("SPARQL response must be an object.");
  const results = value["results"];
  if (!isRecord(results)) throw new TypeError("SPARQL response.results must be an object.");
  const bindings = results["bindings"];
  if (!Array.isArray(bindings)) throw new TypeError("SPARQL response.results.bindings must be an array.");

  return bindings.map((bindingValue, index) => {
    if (!isRecord(bindingValue)) throw new TypeError(`SPARQL binding[${index}] must be an object.`);
    return {
      concept: readBindingValue(bindingValue, "concept", true) ?? "",
      notation: readBindingValue(bindingValue, "notation", true) ?? "",
      label: readBindingValue(bindingValue, "label", true) ?? "",
      broader: readBindingValue(bindingValue, "broader", false),
    };
  });
}

async function fetchSparqlBindings(scheme: string): Promise<readonly SparqlBindingInput[]> {
  const bindings: SparqlBindingInput[] = [];

  for (let offset = 0; ; offset += SPARQL_PAGE_SIZE) {
    const url = new URL(SPARQL_ENDPOINT);
    url.searchParams.set("query", createSparqlQuery(scheme, offset));
    url.searchParams.set("format", "application/sparql-results+json");

    const response = await fetch(url, {headers: {Accept: "application/sparql-results+json"}});
    if (!response.ok) {
      throw new Error(`SPARQL request failed with HTTP ${response.status} ${response.statusText}.`);
    }

    const payload: unknown = await response.json();
    const page = parseSparqlResponse(payload);
    bindings.push(...page);
    if (page.length < SPARQL_PAGE_SIZE) break;
  }

  return bindings;
}

function normalizeSparqlBindings(
  system: Exclude<ArtifactClassificationSystem, "GS1_GPC">,
  version: string,
  bindings: readonly SparqlBindingInput[],
): readonly TaxonomyArtifactNode[] {
  if (version.trim().length === 0) throw new Error("Taxonomy version must not be empty.");

  const codeByConcept = new Map(bindings.map((binding) => [binding.concept, binding.notation] as const));
  const provisional = bindings.map<TaxonomyArtifactNode>((binding) => {
    const label = stripCodePrefix(binding.label, binding.notation);
    const parentCode = binding.broader === null ? null : codeByConcept.get(binding.broader);
    if (binding.broader !== null && parentCode === undefined) {
      throw new Error(`Unresolved parent '${binding.broader}' for taxonomy code '${binding.notation}'.`);
    }

    return {
      code: binding.notation,
      officialLabel: label,
      level: getEuLevel(system, binding.notation),
      parentCode,
      hierarchyCodes: [],
      hierarchyLabels: [],
      definition: null,
      searchText: normalizeText(binding.notation, label),
    };
  });

  return provisional
    .map((node) => buildHierarchy(provisional, node.code))
    .toSorted((left, right) => left.code.localeCompare(right.code, "en", {numeric: true}));
}


function validateArtifact(artifact: TaxonomyArtifact): void {
  if (artifact.nodes.length === 0) throw new Error(`${artifact.system} artifact contains no taxonomy nodes.`);

  const nodesByCode = new Map<string, TaxonomyArtifactNode>();
  for (const node of artifact.nodes) {
    if (nodesByCode.has(node.code)) throw new Error(`${artifact.system} contains duplicate code '${node.code}'.`);
    nodesByCode.set(node.code, node);
  }

  for (const node of artifact.nodes) {
    if (node.parentCode !== null && !nodesByCode.has(node.parentCode)) {
      throw new Error(`${artifact.system} parent '${node.parentCode}' for '${node.code}' was not found.`);
    }
    if (node.hierarchyCodes.at(-1) !== node.code) {
      throw new Error(`${artifact.system} hierarchy for '${node.code}' does not end with the selected code.`);
    }
    if (node.hierarchyCodes.length !== node.hierarchyLabels.length) {
      throw new Error(`${artifact.system} hierarchy for '${node.code}' has mismatched code and label lengths.`);
    }
  }
}

/**
 * Asserts that every mirrored copy read back from disk matches what was written.
 *
 * @remarks
 * Extracted as a pure function so the divergence path is directly unit-testable.
 * Mocking `node:fs/promises` does not intercept the generator's own import under
 * Vitest, so exercising this branch through `writeMirroredArtifacts` is not possible.
 *
 * @param fileName - Generated artifact file name, used only for the error message.
 * @param contents - The exact string that was written to every output root.
 * @param writtenContents - Contents read back from each output root.
 * @throws {Error} When any read-back copy differs from `contents`.
 */
export function assertMirroredContentsIdentical(
  fileName: string,
  contents: string,
  writtenContents: readonly string[],
): void {
  if (writtenContents.some((value) => value !== contents)) {
    throw new Error(`Mirrored artifact '${fileName}' was not written identically.`);
  }
}

/**
 * Writes the same minified artifact into each runtime output directory.
 *
 * @remarks
 * The artifact is validated before any write, and every written file is read back and
 * compared so the API and website copies are provably byte-identical.
 *
 * If one output root fails mid-write the sibling write is not rolled back, so a failed
 * run can leave the roots divergent on disk. Generated artifacts are git-ignored and
 * regenerated on every build, and container builds assert their presence, so the next
 * successful run restores the invariant.
 *
 * @param fileName - Generated artifact file name.
 * @param artifact - Artifact to validate and write.
 * @param outputRoots - Output roots; defaults to the API and website runtime directories.
 * @returns Absolute paths written, in output-root order.
 * @throws {Error} When validation fails or the mirrored copies differ.
 */
export async function writeMirroredArtifacts(
  fileName: string,
  artifact: TaxonomyArtifact,
  outputRoots: readonly string[] = OUTPUT_ROOTS,
): Promise<readonly string[]> {
  validateArtifact(artifact);
  const contents = JSON.stringify(artifact);
  const paths = outputRoots.map((root) => resolve(root, fileName));

  await Promise.all(
    paths.map(async (path, index) => {
      const root = outputRoots[index];
      /* v8 ignore next -- unreachable: paths and outputRoots are mapped from the same array with no mutation between passes. */
      if (root === undefined) throw new Error(`Output root for '${path}' was not found.`);
      await mkdir(root, {recursive: true});
      await writeFile(path, contents, "utf8");
    }),
  );

  const writtenContents = await Promise.all(paths.map((path) => readFile(path, "utf8")));
  assertMirroredContentsIdentical(fileName, contents, writtenContents);

  return paths;
}

/** Extracts one entry from a ZIP archive by delegating to the host operating system. */
export class SystemArchiveExtractor {
  /**
   * Extracts one archive entry selected by suffix.
   *
   * @param archive - Complete ZIP bytes.
   * @param suffix - File-name suffix used to select the extracted entry.
   * @returns Extracted file bytes.
   */
  public async extractEntry(archive: Uint8Array, suffix: string): Promise<Uint8Array> {
    const temporaryRoot = await mkdtemp(join(tmpdir(), "arolariu-taxonomy-"));
    const archivePath = join(temporaryRoot, "source.zip");
    const outputDirectory = join(temporaryRoot, "extracted");
    const extractionCommand = buildArchiveExtractionCommand(process.platform, archivePath, outputDirectory);

    try {
      await mkdir(outputDirectory, {recursive: true});
      await writeFile(archivePath, archive);

      try {
        await executeFile(extractionCommand.command, [...extractionCommand.args]);
      } catch (error: unknown) {
        if (hasErrorCode(error) && error.code === "ENOENT") {
          throw new Error(
            `Required archive extractor '${extractionCommand.command}' was not found on '${process.platform}'.`,
            {cause: error},
          );
        }
        throw error;
      }

      const matchingPaths: string[] = [];
      for await (const extractedPath of glob("**/*", {cwd: outputDirectory})) {
        if (extractedPath.endsWith(suffix)) matchingPaths.push(extractedPath);
      }

      if (matchingPaths.length === 0) {
        throw new Error(`Extracted archive entry ending with '${suffix}' was not found.`);
      }
      if (matchingPaths.length > 1) {
        throw new Error(`Extracted archive contains multiple entries ending with '${suffix}'.`);
      }

      const matchingPath = matchingPaths[0];
      if (matchingPath === undefined) {
        throw new Error(`Extracted archive entry ending with '${suffix}' was not found.`);
      }

      return new Uint8Array(await readFile(join(outputDirectory, matchingPath)));
    } finally {
      await rm(temporaryRoot, {recursive: true, force: true});
    }
  }
}

const GPC_SOURCE = "https://ref.gs1.org/standards/gpc/2026-05/";
const GPC_VERSION = "2026-05";
const GPC_ATTRIBUTION = "GS1 Global Product Classification (GPC), May 2026 release.";

/** Generates the official GS1 GPC taxonomy artifact. */
export class Gs1GpcTaxonomyClassificationGenerator extends TaxonomyClassificationGenerator {
  /** Creates the generator. */
  public constructor(private readonly outputRoots: readonly string[] = OUTPUT_ROOTS) {
    super();
  }

  /** Downloads, validates, normalizes, and writes the GPC artifact. */
  public override async generate(): Promise<readonly string[]> {
    const response = await fetch(GPC_SOURCE, {headers: {Accept: "application/zip"}});
    if (!response.ok) {
      throw new Error(`GPC download failed with HTTP ${response.status} ${response.statusText}.`);
    }

    const archive = new Uint8Array(await response.arrayBuffer());
    const jsonBytes = await new SystemArchiveExtractor().extractEntry(archive, " EN.json");
    const parsed: unknown = JSON.parse(Buffer.from(jsonBytes).toString("utf8"));
    const source = parseGpcDocument(parsed);
    if (source.LanguageCode !== "EN") {
      throw new Error(`Expected English GPC data but received '${source.LanguageCode}'.`);
    }

    const artifact: TaxonomyArtifact = {
      system: "GS1_GPC",
      version: GPC_VERSION,
      sourceUrl: GPC_SOURCE,
      generatedAt: new Date().toISOString(),
      attribution: GPC_ATTRIBUTION,
      nodes: flattenGpcSchema(source.Schema),
    };

    return writeMirroredArtifacts(FILE_NAMES.GS1_GPC, artifact, this.outputRoots);
  }
}

